import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { 
  Card, 
  Table, 
  Tag, 
  Title, 
  Text,
  Alert,
  Space,
  Input,
  Button,
  DatePicker
} from '../components/BasicUI';

const Analysis = () => {
  const [analysis, setAnalysis] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [selectedDate, setSelectedDate] = useState('');

  const fetchAnalysis = async (date = null) => {
    setLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams();
      if (date) {
        params.append('date', date);
      }

      const response = await axios.get(`/api/games/summary?${params.toString()}`);
      setAnalysis(response.data.data || []);
    } catch (err) {
      setError('Error al cargar el análisis: ' + (err.response?.data?.message || err.message));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAnalysis();
  }, []);

  const getLevelColor = (level) => {
    switch (level) {
      case 'Diamond': return 'red';
      case 'Exclusive': return 'orange';
      case 'VIP': return 'blue';
      default: return 'default';
    }
  };

  const columns = [
    {
      title: 'Fecha',
      dataIndex: 'game_date',
      render: (date) => new Date(date).toLocaleDateString('es-ES')
    },
    {
      title: 'Visitante',
      dataIndex: 'away_team_name',
    },
    {
      title: 'Local',
      dataIndex: 'home_team_name',
    },
    {
      title: 'Prob. Visitante',
      dataIndex: 'away_probability',
      render: (prob) => `${(prob * 100).toFixed(1)}%`
    },
    {
      title: 'Prob. Local',
      dataIndex: 'home_probability',
      render: (prob) => `${(prob * 100).toFixed(1)}%`
    },
    {
      title: 'Odds Visitante',
      dataIndex: 'away_american_odds',
      render: (odds) => odds > 0 ? `+${odds}` : odds
    },
    {
      title: 'Odds Local',
      dataIndex: 'home_american_odds',
      render: (odds) => odds > 0 ? `+${odds}` : odds
    },
    {
      title: 'Nivel',
      dataIndex: 'level',
      render: (level) => (
        <Tag color={getLevelColor(level)}>
          {level}
        </Tag>
      )
    }
  ];

  return (
    <div className="analysis-page">
      <Title level={1}>Análisis de Partidos</Title>

      <Space direction="vertical" size="large">
        {error && (
          <Alert
            type="error"
            message="Error"
            description={error}
          />
        )}

        <Card title="Resultados del Análisis">
          <Table
            columns={columns}
            dataSource={analysis}
            loading={loading}
          />
        </Card>

        {analysis.length === 0 && !loading && (
          <Alert
            type="info"
            message="No hay análisis disponibles"
            description="Analiza algunos partidos desde la página de inicio para ver los resultados aquí."
          />
        )}
      </Space>
    </div>
  );
};

export default Analysis;
